def _fit_bank(x, y, prior):
    gain, offset = prior
    i, j = np.triu_indices(x.size, 1)
    delta = x[j] - x[i]
    valid = np.abs(delta) > 1e-10
    if not valid.any():
        return (gain, float(np.median(y - gain * x)) if x.size else offset)
    seed_gain = np.median((y[j[valid]] - y[i[valid]]) / delta[valid])
    residual = y - seed_gain * x
    residual -= np.median(residual)
    keep = np.abs(residual) <= max(1e-07, 5 * np.median(np.abs(residual)))
    if keep.sum() >= 2 and np.ptp(x[keep]) > 1e-10:
        a, b = np.linalg.lstsq(np.column_stack((x[keep], np.ones(keep.sum()))), y[keep], rcond=None)[0]
        if a > 0:
            return (float(a), float(b))
    return (gain, float(np.median(y - gain * x)))

def _project(v, cap, budget):
    lo, hi = (v.min() - cap, v.max())
    for _ in range(55):
        mid = (lo + hi) / 2
        if np.clip(v - mid, 0, cap).sum() > budget:
            lo = mid
        else:
            hi = mid
    return np.clip(v - (lo + hi) / 2, 0, cap)

def _linear_minimum(g, cap, budget):
    fill = np.clip(budget - cap * np.arange(g.size), 0, cap)
    return np.sort(g) @ fill

def _fit_sweep(x, y, prior):
    """Fit the current affine line, with the archived line breaking sparse ties."""
    gain, offset = prior
    if not x.size:
        return prior
    i, j = np.triu_indices(x.size, 1)
    span = x[j] - x[i]
    distinct = np.abs(span) > 1e-08
    i, j, span = (i[distinct], j[distinct], span[distinct])
    slopes = (y[j] - y[i]) / span
    models = [(gain, offset), (gain, np.median(y - gain * x))]
    models.extend(((a, y[k] - a * x[k]) for a, k in zip(slopes, i) if a > 0))
    med = np.median(slopes) if slopes.size else gain
    resid = y - med * x
    mad = np.median(np.abs(resid - np.median(resid)))
    tol = np.clip(4 * mad, 2e-06, 0.02)

    def score(model):
        a, b = model
        err = np.abs(y - a * x - b)
        return ((err <= tol).sum(), -np.mean(np.minimum(err, tol)), -abs(a - gain) - abs(b - offset))
    best = max(models, key=score)
    keep = np.abs(y - best[0] * x - best[1]) <= tol
    if keep.sum() >= 3 and np.ptp(x[keep]) > 1e-08:
        a, b = np.linalg.lstsq(np.column_stack((x[keep], np.ones(keep.sum()))), y[keep], rcond=None)[0]
        if a > 0:
            return (a, b)
    if np.max(np.abs(y - gain * x - offset)) <= 2e-06:
        return (gain, np.median(y - gain * x))
    if x.size == 1 or (x.size == 2 and np.min(np.abs(y - gain * x - offset)) <= 2e-06):
        return prior
    return best

def _profile(values, nuisance, ridge):
    basis, sigma, _ = np.linalg.svd(nuisance, full_matrices=False)
    square = sigma ** 2
    denom = square + ridge
    shrink = np.divide(square, denom, out=np.zeros_like(square), where=denom > 0)
    return values - basis @ (shrink[:, None] * (basis.T @ values))
